-- Phase 3: campaign execution, proof, review and reward approval.
-- Uses the existing campaigns / participations / community_earnings_ledger model.
-- No payout provider is introduced here.

alter table public.campaigns add column if not exists instructions text;
alter table public.campaign_participations add column if not exists reward_status text not null default 'pending', add column if not exists reward_approved_at timestamptz;
alter table public.campaign_participations drop constraint if exists campaign_participations_status_check;
alter table public.campaign_participations add constraint campaign_participations_status_check check (status in ('selected','ready','in_progress','submitted','under_review','completed','rejected','cancelled','expired'));
alter table public.campaign_participations add constraint campaign_participations_reward_status_check check (reward_status in ('pending','approved','payable'));
alter table public.community_earnings_ledger add column if not exists participation_id uuid, add column if not exists entry_type text not null default 'community_reward', add column if not exists reference_id uuid;
create unique index if not exists community_earnings_ledger_participation_uidx on public.community_earnings_ledger(participation_id) where participation_id is not null;

create table if not exists public.campaign_deliverables (
 id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade,
 title text not null, description text not null default '',
 type text not null default 'other' check (type in ('post_message','share_link','instagram_story','whatsapp_post','telegram_post','discord_announcement','screenshot_proof','url_proof','other')),
 required boolean not null default true, deadline timestamptz, reward_amount numeric(14,2) check (reward_amount is null or reward_amount >= 0), display_order integer not null default 0,
 instructions text, required_text text, destination_url text, tracking_url text, content_requirements text, prohibited_modifications text, timing text, submission_requirements text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.campaign_deliverable_progress (
 id uuid primary key default gen_random_uuid(), participation_id uuid not null references public.campaign_participations(id) on delete cascade,
 deliverable_id uuid not null references public.campaign_deliverables(id) on delete cascade,
 status text not null default 'not_started' check (status in ('not_started','in_progress','submitted','revision_required','resubmitted','approved','rejected')),
 started_at timestamptz, last_submitted_at timestamptz, updated_at timestamptz not null default now(), unique(participation_id,deliverable_id)
);
create table if not exists public.campaign_submissions (
 id uuid primary key default gen_random_uuid(), participation_id uuid not null references public.campaign_participations(id) on delete cascade,
 deliverable_id uuid not null references public.campaign_deliverables(id) on delete cascade,
 submitted_by uuid not null references auth.users(id) on delete cascade,
 submission_type text not null check (submission_type in ('screenshot','url','text_note','platform_url','metric')),
 content text, metric_value numeric(18,2), file_path text,
 status text not null default 'submitted' check (status in ('submitted','revision_required','approved','rejected')),
 submitted_at timestamptz not null default now(), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, review_reason text,
 revision_count integer not null default 0 check (revision_count >= 0), version_no integer not null default 1 check (version_no > 0),
 supersedes_submission_id uuid references public.campaign_submissions(id) on delete set null, created_at timestamptz not null default now(),
 unique(participation_id,deliverable_id,version_no)
);
create table if not exists public.campaign_execution_audit (
 id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade,
 participation_id uuid references public.campaign_participations(id) on delete cascade,
 deliverable_id uuid references public.campaign_deliverables(id) on delete cascade,
 submission_id uuid references public.campaign_submissions(id) on delete cascade,
 actor_user_id uuid references auth.users(id) on delete set null, actor_type text not null check (actor_type in ('admin','brand','controller','system')),
 action text not null, details jsonb, created_at timestamptz not null default now()
);
create index if not exists campaign_deliverables_campaign_idx on public.campaign_deliverables(campaign_id,display_order);
create index if not exists campaign_progress_participation_idx on public.campaign_deliverable_progress(participation_id,status);
create index if not exists campaign_submissions_participation_idx on public.campaign_submissions(participation_id,deliverable_id,version_no desc);
create index if not exists campaign_execution_audit_campaign_idx on public.campaign_execution_audit(campaign_id,created_at desc);

create or replace function public.seed_participation_deliverables() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.campaign_deliverable_progress(participation_id,deliverable_id) select new.id,d.id from public.campaign_deliverables d where d.campaign_id=new.campaign_id on conflict(participation_id,deliverable_id) do nothing; return new; end;$$;
revoke all on function public.seed_participation_deliverables() from public,anon,authenticated;
drop trigger if exists trg_seed_participation_deliverables on public.campaign_participations;
create trigger trg_seed_participation_deliverables after insert on public.campaign_participations for each row execute function public.seed_participation_deliverables();
create or replace function public.seed_deliverable_progress_for_existing_participations() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.campaign_deliverable_progress(participation_id,deliverable_id) select p.id,new.id from public.campaign_participations p where p.campaign_id=new.campaign_id on conflict(participation_id,deliverable_id) do nothing; return new; end;$$;
revoke all on function public.seed_deliverable_progress_for_existing_participations() from public,anon,authenticated;
drop trigger if exists trg_seed_deliverable_progress on public.campaign_deliverables;
create trigger trg_seed_deliverable_progress after insert on public.campaign_deliverables for each row execute function public.seed_deliverable_progress_for_existing_participations();

create or replace function public.start_campaign_participation(p_participation_id uuid) returns public.campaign_participations language plpgsql security definer set search_path='' as $$declare r public.campaign_participations; c public.campaigns;begin select p.* into r from public.campaign_participations p where p.id=p_participation_id and p.admin_user_id=(select auth.uid()); if r.id is null then raise exception 'Participation not found or not authorized'; end if; select * into c from public.campaigns where id=r.campaign_id; if c.status <> 'active' then raise exception 'Campaign is not active'; end if; if c.ends_at is not null and c.ends_at < now() then raise exception 'Campaign has ended'; end if; if r.status not in ('selected','ready') then raise exception 'Participation cannot be started from status %',r.status; end if; update public.campaign_participations set status='in_progress',updated_at=now() where id=r.id returning * into r; insert into public.campaign_execution_audit(campaign_id,participation_id,actor_user_id,actor_type,action,details) values(r.campaign_id,r.id,(select auth.uid()),'admin','participation_started','{}'); insert into public.owner_notifications(user_id,community_id,title,message,kind,href) values(r.admin_user_id,r.community_id,'Campaign started','Your campaign task is ready to work on.','success','/dashboard/rewards/'||r.campaign_id::text); return r;end;$$;
revoke all on function public.start_campaign_participation(uuid) from public,anon,authenticated; grant execute on function public.start_campaign_participation(uuid) to authenticated;

create or replace function public.start_campaign_deliverable(p_participation_id uuid,p_deliverable_id uuid) returns public.campaign_deliverable_progress language plpgsql security definer set search_path='' as $$declare r public.campaign_deliverable_progress; p public.campaign_participations; d public.campaign_deliverables;begin select * into p from public.campaign_participations where id=p_participation_id and admin_user_id=(select auth.uid()); if p.id is null then raise exception 'Participation not found or not authorized'; end if; select * into d from public.campaign_deliverables where id=p_deliverable_id and campaign_id=p.campaign_id; if d.id is null then raise exception 'Deliverable not found'; end if; if p.status not in ('in_progress','submitted','under_review') then raise exception 'Participation is not active'; end if; if d.deadline is not null and d.deadline < now() then raise exception 'Deliverable deadline has passed'; end if; insert into public.campaign_deliverable_progress(participation_id,deliverable_id,status,started_at,updated_at) values(p.id,d.id,'in_progress',now(),now()) on conflict(participation_id,deliverable_id) do update set status=case when public.campaign_deliverable_progress.status in ('not_started','revision_required','resubmitted') then 'in_progress' else public.campaign_deliverable_progress.status end,started_at=coalesce(public.campaign_deliverable_progress.started_at,now()),updated_at=now() returning * into r; insert into public.campaign_execution_audit(campaign_id,participation_id,deliverable_id,actor_user_id,actor_type,action,details) values(p.campaign_id,p.id,d.id,(select auth.uid()),'admin','deliverable_started','{}'); return r;end;$$;
revoke all on function public.start_campaign_deliverable(uuid,uuid) from public,anon,authenticated; grant execute on function public.start_campaign_deliverable(uuid,uuid) to authenticated;

create or replace function public.change_campaign_status(p_campaign_id uuid,p_status text) returns public.campaigns language plpgsql security definer set search_path='' as $$declare r public.campaigns; old_status text; deliverable_count int;begin select c.status into old_status from public.campaigns c where c.id=p_campaign_id and c.brand_user_id=(select auth.uid()); if old_status is null then raise exception 'Campaign not found or not authorized'; end if; if old_status='pending_review' and p_status='active' then select count(*) into deliverable_count from public.campaign_deliverables d where d.campaign_id=p_campaign_id; if deliverable_count=0 then raise exception 'Campaign needs at least one deliverable before activation'; end if; end if; if not ((old_status='draft' and p_status='pending_review') or (old_status='pending_review' and p_status in ('active','cancelled')) or (old_status='active' and p_status in ('paused','completed','cancelled')) or (old_status='paused' and p_status in ('active','completed','cancelled'))) then raise exception 'Invalid campaign status transition: % -> %',old_status,p_status; end if; update public.campaigns set status=p_status,updated_at=now() where id=p_campaign_id returning * into r; return r;end;$$;
revoke all on function public.change_campaign_status(uuid,text) from public,anon,authenticated; grant execute on function public.change_campaign_status(uuid,text) to authenticated;

create or replace function public.submit_campaign_deliverable_record(p_participation_id uuid,p_deliverable_id uuid,p_submission_type text,p_content text,p_metric_value numeric,p_file_path text) returns public.campaign_submissions language plpgsql security definer set search_path='' as $$declare p public.campaign_participations; d public.campaign_deliverables; c public.campaigns; prev public.campaign_submissions; s public.campaign_submissions; next_version int;begin if p_submission_type not in ('screenshot','url','text_note','platform_url','metric') then raise exception 'Invalid submission type'; end if; select * into p from public.campaign_participations where id=p_participation_id and admin_user_id=(select auth.uid()); if p.id is null then raise exception 'Participation not found or not authorized'; end if; select * into d from public.campaign_deliverables where id=p_deliverable_id and campaign_id=p.campaign_id; if d.id is null then raise exception 'Deliverable not found for this campaign'; end if; select * into c from public.campaigns where id=p.campaign_id; if c.status <> 'active' then raise exception 'Campaign is not active'; end if; if c.ends_at is not null and c.ends_at < now() then raise exception 'Campaign has ended'; end if; if d.deadline is not null and d.deadline < now() then raise exception 'Deliverable deadline has passed'; end if; if p.status not in ('in_progress','submitted','under_review') then raise exception 'Participation is not accepting submissions from status %',p.status; end if; if p_submission_type='screenshot' and nullif(trim(coalesce(p_file_path,'')),'') is null then raise exception 'Screenshot submission requires a file'; end if; if p_submission_type in ('url','platform_url') and nullif(trim(coalesce(p_content,'')),'') is null then raise exception 'URL submission requires a URL'; end if; if p_submission_type='text_note' and nullif(trim(coalesce(p_content,'')),'') is null then raise exception 'Text submission requires content'; end if; select * into prev from public.campaign_submissions where participation_id=p.id and deliverable_id=d.id order by version_no desc limit 1; next_version := coalesce(prev.version_no,0)+1; insert into public.campaign_submissions(participation_id,deliverable_id,submitted_by,submission_type,content,metric_value,file_path,status,submitted_at,revision_count,version_no,supersedes_submission_id) values(p.id,d.id,(select auth.uid()),p_submission_type,nullif(trim(coalesce(p_content,'')),''),p_metric_value,nullif(trim(coalesce(p_file_path,'')),''),'submitted',now(),case when prev.status='revision_required' then coalesce(prev.revision_count,0)+1 else coalesce(prev.revision_count,0) end,next_version,prev.id) returning * into s; insert into public.campaign_deliverable_progress(participation_id,deliverable_id,status,last_submitted_at,updated_at) values(p.id,d.id,case when prev.id is null then 'submitted' else 'resubmitted' end,now(),now()) on conflict(participation_id,deliverable_id) do update set status=excluded.status,last_submitted_at=excluded.last_submitted_at,updated_at=now(); update public.campaign_participations set status='submitted',updated_at=now() where id=p.id; insert into public.campaign_execution_audit(campaign_id,participation_id,deliverable_id,submission_id,actor_user_id,actor_type,action,details) values(c.id,p.id,d.id,s.id,(select auth.uid()),'admin','submission_created',jsonb_build_object('submission_type',p_submission_type,'version_no',next_version)); return s;end;$$;
revoke all on function public.submit_campaign_deliverable_record(uuid,uuid,text,text,numeric,text) from public,anon,authenticated; grant execute on function public.submit_campaign_deliverable_record(uuid,uuid,text,text,numeric,text) to authenticated;

create or replace function public.review_campaign_submission(p_submission_id uuid,p_status text,p_reason text default null) returns public.campaign_submissions language plpgsql security definer set search_path='' as $$declare s public.campaign_submissions; p public.campaign_participations; d public.campaign_deliverables; c public.campaigns; all_required boolean; reward numeric; reviewer uuid; community_name text;begin reviewer := (select auth.uid()); if p_status not in ('approved','revision_required','rejected') then raise exception 'Invalid submission review status'; end if; select * into s from public.campaign_submissions where id=p_submission_id; if s.id is null then raise exception 'Submission not found'; end if; select * into p from public.campaign_participations where id=s.participation_id; select * into d from public.campaign_deliverables where id=s.deliverable_id; select * into c from public.campaigns where id=p.campaign_id; select co.name into community_name from public.communities co where co.id=p.community_id; if c.brand_user_id <> reviewer then raise exception 'Not authorized to review this submission'; end if; if s.status <> 'submitted' then raise exception 'Only a submitted proof can be reviewed'; end if; if p_status='revision_required' and coalesce(trim(p_reason),'')='' then raise exception 'Revision reason is required'; end if; update public.campaign_submissions set status=p_status,reviewed_by=reviewer,reviewed_at=now(),review_reason=nullif(trim(coalesce(p_reason,'')),'') where id=s.id returning * into s; update public.campaign_deliverable_progress set status=case when p_status='revision_required' then 'revision_required' when p_status='rejected' then 'rejected' else 'approved' end,last_submitted_at=s.submitted_at,updated_at=now() where participation_id=s.participation_id and deliverable_id=s.deliverable_id; insert into public.campaign_execution_audit(campaign_id,participation_id,deliverable_id,submission_id,actor_user_id,actor_type,action,details) values(c.id,p.id,d.id,s.id,reviewer,'brand','submission_'||p_status,jsonb_build_object('reason',nullif(trim(coalesce(p_reason,'')),''))); if p_status='revision_required' then update public.campaign_participations set status='in_progress',updated_at=now() where id=p.id; insert into public.owner_notifications(user_id,community_id,title,message,kind,href) values(p.admin_user_id,p.community_id,'Revision requested',coalesce(c.title,'Campaign')||' needs changes to your '||coalesce(d.title,'submission')||'.','warning','/dashboard/rewards/'||c.id::text); elsif p_status='rejected' then update public.campaign_participations set status='rejected',updated_at=now() where id=p.id; insert into public.owner_notifications(user_id,community_id,title,message,kind,href) values(p.admin_user_id,p.community_id,'Submission rejected',coalesce(c.title,'Campaign')||' rejected your '||coalesce(d.title,'submission')||'.','warning','/dashboard/rewards/'||c.id::text); else select not exists(select 1 from public.campaign_deliverables rd where rd.campaign_id=c.id and rd.required=true and not exists(select 1 from public.campaign_deliverable_progress dp where dp.participation_id=p.id and dp.deliverable_id=rd.id and dp.status='approved')) into all_required; if all_required then reward := coalesce(p.committed_reward,0); if reward <= 0 then raise exception 'No positive committed reward is configured for this participation'; end if; update public.campaign_participations set status='completed',reward_status='approved',reward_approved_at=coalesce(reward_approved_at,now()),updated_at=now() where id=p.id and reward_status<>'approved'; insert into public.community_earnings_ledger(user_id,community_id,campaign_id,participation_id,amount,currency,status,entry_type,reference_id,description) values(p.admin_user_id,p.community_id,p.campaign_id,p.id,reward,'INR','approved','campaign_reward',s.id,'Approved reward for '||coalesce(c.title,'campaign')) on conflict(participation_id) where participation_id is not null do nothing; insert into public.owner_notifications(user_id,community_id,title,message,kind,href) values(p.admin_user_id,p.community_id,'Reward approved','₹'||trim(to_char(reward,'FM999999999990.00'))||' has been added to your Community Rewards earnings. This is not a bank/UPI payout.','success','/dashboard/rewards'); else update public.campaign_participations set status='under_review',updated_at=now() where id=p.id; insert into public.owner_notifications(user_id,community_id,title,message,kind,href) values(p.admin_user_id,p.community_id,'Submission approved',coalesce(d.title,'Deliverable')||' was approved. Remaining required deliverables are still pending.','success','/dashboard/rewards/'||c.id::text); end if; end if; return s;end;$$;
revoke all on function public.review_campaign_submission(uuid,text,text) from public,anon,authenticated; grant execute on function public.review_campaign_submission(uuid,text,text) to authenticated;

alter table public.campaign_deliverables enable row level security;
alter table public.campaign_deliverable_progress enable row level security;
alter table public.campaign_submissions enable row level security;
alter table public.campaign_execution_audit enable row level security;
create policy campaign_deliverables_brand_select on public.campaign_deliverables for select to authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_deliverables.campaign_id and c.brand_user_id=(select auth.uid())));
create policy campaign_deliverables_admin_select on public.campaign_deliverables for select to authenticated using(exists(select 1 from public.campaign_participations p where p.campaign_id=campaign_deliverables.campaign_id and p.admin_user_id=(select auth.uid())));
create policy campaign_deliverables_brand_write on public.campaign_deliverables for all to authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_deliverables.campaign_id and c.brand_user_id=(select auth.uid()) and c.status in ('draft','pending_review'))) with check(exists(select 1 from public.campaigns c where c.id=campaign_deliverables.campaign_id and c.brand_user_id=(select auth.uid()) and c.status in ('draft','pending_review')));
create policy campaign_progress_admin_select on public.campaign_deliverable_progress for select to authenticated using(exists(select 1 from public.campaign_participations p where p.id=campaign_deliverable_progress.participation_id and p.admin_user_id=(select auth.uid())));
create policy campaign_progress_brand_select on public.campaign_deliverable_progress for select to authenticated using(exists(select 1 from public.campaign_participations p join public.campaigns c on c.id=p.campaign_id where p.id=campaign_deliverable_progress.participation_id and c.brand_user_id=(select auth.uid())));
create policy campaign_submissions_admin_select on public.campaign_submissions for select to authenticated using(submitted_by=(select auth.uid()));
create policy campaign_submissions_brand_select on public.campaign_submissions for select to authenticated using(exists(select 1 from public.campaign_participations p join public.campaigns c on c.id=p.campaign_id where p.id=campaign_submissions.participation_id and c.brand_user_id=(select auth.uid())));
create policy campaign_submissions_admin_insert on public.campaign_submissions for insert to authenticated with check(submitted_by=(select auth.uid()) and exists(select 1 from public.campaign_participations p where p.id=campaign_submissions.participation_id and p.admin_user_id=(select auth.uid())));
create policy campaign_execution_audit_admin_read on public.campaign_execution_audit for select to authenticated using(exists(select 1 from public.campaign_participations p where p.id=campaign_execution_audit.participation_id and p.admin_user_id=(select auth.uid())));
create policy campaign_execution_audit_brand_read on public.campaign_execution_audit for select to authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_execution_audit.campaign_id and c.brand_user_id=(select auth.uid())));
revoke update,insert on public.community_earnings_ledger from anon,authenticated;
revoke update,insert on public.campaign_participations from anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('campaign-proof','campaign-proof',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;
